// Canary CloudWatch Synthetics `prestare-health` (sa-east-1, a cada 15 min).
// Alarme: prestare-canary-falha (SuccessPercent < 100 em 2 ciclos). Runbook: docs/operacao/runbooks.md §5.7.
//
// Passos:
//   api-health  — GET /api/health da API pública (CloudFront -> ALB -> EB) precisa dar 200.
//   site-sobre  — GET /sobre/ do portal (Amplify) precisa terminar em 200, seguindo até 3 redirecionamentos.
//
// Histórico: a versão anterior (não versionada) exigia 200 direto em /sobre; quando o Amplify passou a
// responder 301 para /sobre/, o canary falhou a partir de 09/11/2026, foi parado em 12/11 e o alarme
// ficou em ALARM sem ninguém olhar. Recriado em 25/11/2026 (bateria de testes de produção).
//
// Publicar: ver scripts/ops/canary/README.md.
const synthetics = require('Synthetics');
const log = require('SyntheticsLogger');
const https = require('https');

const TIMEOUT_MS = 15000;
const MAX_REDIRECIONAMENTOS = 3;

function obterStatus(url, saltos = 0) {
  return new Promise((resolve, reject) => {
    const req = https.get(url, { timeout: TIMEOUT_MS, headers: { 'User-Agent': 'prestare-canary/2' } }, (res) => {
      res.resume();
      const destino = res.headers.location;
      if ([301, 302, 307, 308].includes(res.statusCode) && destino) {
        if (saltos >= MAX_REDIRECIONAMENTOS) return reject(new Error(`${url}: redirecionamentos demais`));
        return resolve(obterStatus(new URL(destino, url).toString(), saltos + 1));
      }
      res.on('end', () => resolve({ status: res.statusCode, url }));
      res.on('error', reject);
    });
    req.on('timeout', () => req.destroy(new Error(`${url}: timeout de ${TIMEOUT_MS} ms`)));
    req.on('error', reject);
  });
}

async function checar(nome, url) {
  await synthetics.executeStep(nome, async () => {
    const inicio = Date.now();
    const { status, url: final } = await obterStatus(url);
    log.info(`${nome}: ${url} -> ${final} status ${status} em ${Date.now() - inicio} ms`);
    if (status !== 200) throw new Error(`${final} status ${status}`);
  });
}

exports.handler = async () => {
  await checar('api-health', 'https://api.prestarecondominios.com.br/api/health');
  await checar('site-sobre', 'https://www.prestarecondominios.com.br/sobre/');
};
